export function dedupeNames(names) {
  if (names.length === 0) return [];
  const seen = new Set();
  const result = [];
  for (const name of names) {
    if (!seen.has(name)) {
      seen.add(name);
      result.push(name);
    }
  }
  return result;
}

export default function sliceLines(text, offset = 1, limit = 2000) {
  // Adjust offset and limit
  offset = Math.max(1, Math.min(offset, 2000));
  limit = Math.max(1, Math.min(limit, 2000));

  // Split text into lines
  const lines = text.split(/?
/g);

  // Calculate start and end indices
  const start = offset - 1;
  const end = start + limit;

  // Clamp end to 2000
  end = Math.min(end, 2000);

  // Handle edge cases
  if (start >= lines.length) {
    return [];
  }

  // Handle end beyond array
  const sliced = lines.slice(start, end);

  if (end > lines.length) {
    sliced = lines.slice(start, lines.length);
  }

  return sliced;
